function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function isPrime(n) {
  if (!Number.isInteger(n) || n <= 1) return false;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}

module.exports = { clamp, isPrime };
